"""Find Pivot Index — compare running left sum against the remainder.

Time: O(n)   Space: O(1)
"""
from typing import List


class Solution:
    def pivotIndex(self, nums: List[int]) -> int:
        total, left = sum(nums), 0
        for i, value in enumerate(nums):
            if left == total - left - value:
                return i
            left += value
        return -1
